// Strokes: the points of the centerline in 1/64 pixel, whether it is closed, the width in 1/64 pixel, the cap (0 butt, 1 square), the
// alignment (0 center, 1 inside, 2 outside), joined by miters; and the pixels covered.
struct Stroke {
  const char * name;
  int count;
  const int * points;
  int closed;
  int width;
  int cap;
  int align;
  const char * covered;
};

